function recordClientError(message,details={}){
  if(String(details.path||'').startsWith('/api/support/errors'))return;
  const payload={message:String(message||'Ошибка интерфейса').slice(0,2000),source:'web-ui',view:location.hash||'#overview',...details};
  fetch('/api/support/errors',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),keepalive:true}).catch(()=>{});
}

async function api(url, options={}){
  const res=await fetch(url, options);
  const ct=res.headers.get('content-type')||'';
  const body=ct.includes('json')?await res.json():await res.text();
  if(!res.ok){const error=new Error((body&&body.message)||(body&&body.error)||String(body)||`HTTP ${res.status}`);error.status=res.status;error.payload=body;recordClientError(error.message,{path:url,status:res.status,action:options.method||'GET'});throw error}
  return body;
}
window.addEventListener('error',event=>recordClientError(event.message,{action:'window.error',path:event.filename||location.pathname,line:event.lineno,column:event.colno}));
window.addEventListener('unhandledrejection',event=>recordClientError(event.reason?.message||String(event.reason||'Необработанная ошибка'),{action:'unhandledrejection',path:location.pathname}));
