 const grid=$('workflow-grid');grid.innerHTML=arr(w.steps).map((x,i)=>`<article class="workflow-step ${esc(x.status)}"><div class="step-number">${i+1}</div><div><strong>${esc(x.title)}</strong><p>${workflowHint(x.id)}</p></div><span>${statusLabel(x.status)}</span></article>`).join('');
