function uniqueOptions(values,allLabel){const vals=[...new Set(values.map(cleanValue).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ru'));return `<option value="all">${esc(allLabel)}</option>`+vals.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}
function setSelectOptions(id,html){const el=$(id);if(!el)return;const old=el.value;el.innerHTML=html;if([...el.options].some(o=>o.value===old))el.value=old}
