 return arr(state.data.rules).filter(r=>{const v=ruleMappingView(r),ap=approvalFor(r),decision=ap?.decision||'UNCONFIRMED';if(q&&!ruleSearchText(r).includes(q))return false;if(!ruleMatchesOrganization(r,org,includeChildren))return false;if(origin!=='all'&&r.rule_type!==origin)return false;if(action!=='all'&&r.action!==action)return false;if(year!=='all'){const y=Number(year),a=Number(r.valid_from_year||0),b=r.valid_to_year?Number(r.valid_to_year):9999;if(!(y>=a&&y<=b))return false}if(status!=='all'){if(['ADOPTED','DISPUTED','REJECTED','UNCONFIRMED'].includes(status)){if(decision!==status)return false}else if(r.status!==status)return false}if(ib!=='all'&&v.intalevBlock!==ib)return false;if(ia!=='all'&&v.intalevArticle!==ia)return false;if(idt!=='all'&&v.intalevDebit!==idt)return false;if(ikt!=='all'&&v.intalevCredit!==ikt)return false;if(eb!=='all'&&v.erpBlock!==eb)return false;if(ea!=='all'&&v.erpArticle!==ea)return false;if(edt!=='all'&&v.erpDebit!==edt)return false;if(ekt!=='all'&&v.erpCredit!==ekt)return false;return true})
