 const pairRule=lineCodes.length>1,intPath=cleanValue(v.is.path),rightArticle=pairRule?articleLabel(v.it,'intalev'):v.erpArticle,rightBlock=pairRule?cleanValue(v.it.block||blockFromPath(v.it.path,v.it.article)):v.erpBlock,rightPath=pairRule?cleanValue(v.it.path):cleanValue(v.erpObj.path),route=`${v.intalevArticle} → ${rightArticle}`,lineLabel=lineCodes.length?`${lineCodes.length>1?'Строки':'Строка'} ОПИУ: ${lineCodes.join(', ')}`:'';
 const intalevAccounts=(v.intalevDebit||v.intalevCredit)?`Дт ${v.intalevDebit||'—'} / Кт ${v.intalevCredit||'—'}`:v.intalevAccountStatus;
 const erpAccounts=`Дт ${v.erpDebit||'—'} / Кт ${v.erpCredit||'—'}`;
