 const rowEdit=e.target.closest('[data-rules-row-edit]');if(rowEdit){const select=$('rules-engine-result')?.querySelector(`[data-rules-candidate-erp="${CSS.escape(rowEdit.dataset.rulesRowEdit)}"]`);select?.scrollIntoView({block:'center',behavior:'smooth'});select?.focus();return}
 const rowCard=e.target.closest('[data-rules-row-card]');if(rowCard){try{await openRulesEngineCandidateCard(rowCard.dataset.rulesRowCard)}catch(err){toast(err.message,true)}return}
 const rowPosting=e.target.closest('[data-rules-row-posting]');if(rowPosting){const details=$('rules-engine-result')?.querySelector(`[data-rules-evidence-for="${CSS.escape(rowPosting.dataset.rulesRowPosting)}"]`);if(details){details.open=true;details.scrollIntoView({block:'center',behavior:'smooth'})}return}
